#include <sys/wait.h>
#include <sys/resource.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

int main() {
    pid_t child_pid;
    int status;
    struct rusage usage_stats;

    child_pid = fork();

    if (child_pid == -1) {
        perror("fork failed");
        return EXIT_FAILURE;
    }

    if (child_pid == 0) {
        /* Child process: do some work (simulated loop) */
        for (long i = 0; i < 5000000; i++) { /* Burn some CPU time */ }
        printf("[Child %d] Exiting.\n", getpid());
        _exit(10); 
    } else {
        /* Parent process: wait for child and collect resources */
        printf("[Parent %d] Waiting for child %d...\n", getpid(), child_pid);

        /* Wait for the specific child_pid, with default options (0) */
        pid_t terminated_pid = wait4(child_pid, &status, 0, &usage_stats);

        if (terminated_pid == -1) {
            perror("wait4 failed");
            return EXIT_FAILURE;
        }

        if (WIFEXITED(status)) {
            printf("[Parent] Child terminated with status %d.\n", WEXITSTATUS(status));
            printf("[Parent] Resource Usage Collected:\n");

            // Report user CPU time used by the child
            printf(" - User Time: %ld.%06ld seconds\n", 
                   usage_stats.ru_utime.tv_sec, 
                   (long)usage_stats.ru_utime.tv_usec);

            // Report system CPU time used by the child
            printf(" - System Time: %ld.%06ld seconds\n", 
                   usage_stats.ru_stime.tv_sec, 
                   (long)usage_stats.ru_stime.tv_usec);
        }
    }

    return EXIT_SUCCESS;
}
